// --- Safety Guardrails for Thumbnail and Sandbox ---
if (typeof width === 'undefined') { var width = 1280; }
if (typeof height === 'undefined') { var height = 720; }


// --- Global Variables for Uncler M Variants ---
var uM_colors = ["#ffffff", "#000000", "#71717a", "#27272a", "#f4f4f5"];
var speedMult = 1.0;
var lineScale = 1.0;
var dynamicShift = 0;
var scalePulse = 1.0;
var rotAngle = 0;
var gridOffset = 0;
var uM_rot = 0;

// === Inspired by 'TorusKnot' by 'Naoki Tsutae' ===
// Created as variant #5 by Uncler M
// Infused with creative algorithmic modifications.

// === Tab: mySketch ===
// Torus Knot

const numSegment = 320; // Number of segments in the snake
const body = [];
const bodyThin = 60;

// Torus Knot parameters
const p = 2;
const q = 3;
const R = 200;
const r0 = 90;

// Animation speed
const animationSpeed = 100; // frames per full period

// 1 Torus Knot period in t
const tPeriod = Math.PI*2;

// Uniform offset step for 1 full period
const offsetStep = tPeriod / numSegment;

// Compute position along Torus Knot
function getPos(offset) {
  const t = frameCount / animationSpeed - offset; // Time-based animation
  const x = (R + r0 * cos(q * t)) * cos(p * t);
  const y = (R + r0 * cos(q * t)) * sin(p * t);
  const z = r0 * sin(q * t);
  return createVector(x, y, z);
}

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  noStroke();

  // Initialize body segments
  for (let i = 0; i < numSegment; i++) {
    const r = random(5, 70);
    body.push({
      offset: i * offsetStep * 0.9, // Reduce segment spacing to create a gap between head and tail
      angle: random(Math.PI*2),
      color: "#" + hex(random(), 6),
      sizeX: r,
      sizeY: 75 - r
    });
  }
}

function draw() {
  // === Variant 5: Symmetric Kaleidoscope Portal ===
  // Applying kaleidoscope coordinate distortion
  uM_rot = frameCount * 0.005;
  push();
  translate(width/2, height/2);
  rotate(uM_rot);
  scale(1.1);
  translate(-width/2, -height/2);

  background(10, 10, 15);
  orbitControl();

  let prevUp = createVector(0, 0, 1); // Initial Up vector
  let prevTangent = null;

  for (let i = 0; i < body.length; i++) {
    const b = body[i];
    const bodyColor = 
      i === 0 ? "yellow" :    // head segment
      i === body.length - 1 ? "lightblue" : // tail segment
      "black"; // body segments    

    const pos = getPos(b.offset);
    const delta = 0.001;
    const posAhead = getPos(b.offset - delta);

    // Compute tangent vector along the curve
    const tangent = p5.Vector.sub(posAhead, pos).normalize();

    // Parallel transport to update Up vector
    let up;
    if (prevTangent) {
      const axis = prevTangent.cross(tangent);
      const angle = acos(constrain(prevTangent.dot(tangent), -1, 1));
      if (axis.mag() < 0.0001 || angle === 0) {
        up = prevUp.copy();
      } else {
        axis.normalize();
        up = rotateVectorAroundAxis(prevUp, axis, angle);
      }
    } else {
      up = prevUp.copy();
    }

    // Compute Right vector and re-orthogonalize Up
    const right = tangent.cross(up).normalize();
    up = right.cross(tangent).normalize();

    prevUp = up.copy();
    prevTangent = tangent.copy();

    // Draw segment using parallel-transport frame
    push();
    translate(pos.x, pos.y, pos.z);

    applyMatrix(
      tangent.x, tangent.y, tangent.z, 0,
      right.x,   right.y,   right.z,   0,
      up.x,      up.y,      up.z,      0,
      0, 0, 0, 1
    );

    rotateX(b.angle);

    // Draw body sphere
    fill(bodyColor);
    sphere(bodyThin);

    // Draw scale (plane) in local frame
    translate(0, bodyThin, 0);
    fill(b.color);
    rotateX(Math.PI / 2);
    plane(b.sizeX, b.sizeY);

    pop();
  }

  pop();
}

// Rotate vector around axis by angle
function rotateVectorAroundAxis(v, axis, angle) {
  const cosA = cos(angle);
  const sinA = sin(angle);
  return p5.Vector.add(
    p5.Vector.mult(v, cosA),
    p5.Vector.add(
      p5.Vector.mult(axis.cross(v), sinA),
      p5.Vector.mult(axis, axis.dot(v) * (1 - cosA))
    )
  );
}


// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
